                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8"><strong>@shipment.EstimatedDelivery.ToShortDateString()</strong></dd>
            </dl>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task Search()
    {
        searched = true;
        shipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await Search();
        }
    }
}

