using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that provides shipment data directly (no HTTP calls).
/// Used during Server-side rendering and Interactive Server mode.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-1001", Status = "In Transit", Origin = "New York, US", Destination = "London, UK", CustomerEmail = "alice@example.com", ShippedDate = DateTime.Today.AddDays(-3), EstimatedDelivery = DateTime.Today.AddDays(4) },
        new() { Id = 2, TrackingNumber = "TRK-1002", Status = "Pending", Origin = "Shanghai, CN", Destination = "Los Angeles, US", CustomerEmail = "bob@example.com", ShippedDate = DateTime.Today.AddDays(-1), EstimatedDelivery = DateTime.Today.AddDays(10) },
        new() { Id = 3, TrackingNumber = "TRK-1003", Status = "Delivered", Origin = "Berlin, DE", Destination = "Tokyo, JP", CustomerEmail = "carol@example.com", ShippedDate = DateTime.Today.AddDays(-7), EstimatedDelivery = DateTime.Today.AddDays(-1) },
        new() { Id = 4, TrackingNumber = "TRK-1004", Status = "Out for Delivery", Origin = "Sydney, AU", Destination = "Singapore, SG", CustomerEmail = "dave@example.com", ShippedDate = DateTime.Today.AddDays(-5), EstimatedDelivery = DateTime.Today },
        new() { Id = 5, TrackingNumber = "TRK-1005", Status = "In Transit", Origin = "São Paulo, BR", Destination = "Miami, US", CustomerEmail = "eve@example.com", ShippedDate = DateTime.Today.AddDays(-2), EstimatedDelivery = DateTime.Today.AddDays(3) },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
        => Task.FromResult(_shipments.ToList());

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => Task.FromResult(_shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));

    public Task UpdateStatusAsync(int id, string newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = newStatus;
        }
        return Task.CompletedTask;
    }
}

using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            await service.GetAllShipmentsAsync());

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPut("/{id}/status", async (int id, string newStatus, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, newStatus);
            return Results.NoContent();
        });
    }
}

